    var line=lines[i].trim();
    if(!line)continue;
    line=line.replace(/\{\{\s*HP\s*\}\}/gi,'ＨＰ').replace(/\{\{\s*PP\s*\}\}/gi,'PP').replace(/\{\{\s*(?:a|s|m|tt|game2|game)\s*\|([^}|]+)(?:\|[^}]*)?\}\}/gi,function(all,txt){return txt.trim();});
