      if(v===undefined||v===null||v==='')continue;
      var k=String(v);if(!idx[k])idx[k]=data[i];
      if(fields[f]==='en'||fields[f]==='jp'){var lk=k.toLowerCase();if(!idx[lk])idx[lk]=data[i];}
      var hw=normItemName(k);if(hw!==k&&!idx[hw])idx[hw]=data[i];
