  var defs=[v1];
  if(v2&&v2!==v1)defs.push(v2);
  var o4=[],o2=[],o05=[],o025=[],o0=[];
  for(var i=0;i<TYPE_CHART.length;i++){
    var atk=TYPE_CHART[i][0];
    var mul=1;
    for(var j=0;j<defs.length;j++){
      var m=typeMul(atk,defs[j]);
      if(m===0){mul=0;break;}
