          tm=WIN.setTimeout(finish,8000);
          rq.onsuccess=function(){var c=rq.result;if(!c){finish();return;}var v=c.value||{};rows.push({size:Number(v.size||(v.b&&v.b.size)||(v.blob&&v.blob.size)||0)});c.continue();};
